from typing import List

class Solution:
    def partitionLabels(self, s: str) -> List[int]:
        last = {ch: i for i, ch in enumerate(s)}
        ans = []
        start = 0

        while start < len(s):
            end = last[s[start]]
            i = start
            while i <= end:
                end = max(end, last[s[i]])
                i += 1
            ans.append(end - start + 1)
            start = end + 1
        return ans

